<script lang="ts">
  import { page } from '$app/state';
  import { browser } from '$app/environment';
  import { goto } from '$app/navigation';
  import Icon from '$lib/components/Icon.svelte';
  import FileGlyph from '$lib/components/FileGlyph.svelte';
  import StatusPill from '$lib/components/StatusPill.svelte';
  import { catalogueCategories } from '$lib/stores/catalogue';
  import { creatorProfile, creatorProducts, loadCreatorData, removeCreatorProduct, setProductStatus, storefront, updateCreatorProduct } from '$lib/stores/creator';
  import { showToast } from '$lib/stores/marketplace';
  import { apiRequest } from '$lib/api';
  import { uploadFileToR2, type R2BrowserUpload } from '$lib/r2-upload';
  import { getSupabaseBrowserClient } from '$lib/supabase/client';
  import { parseShowcaseVideoUrl } from '$lib/showcase-video';

  let tab=page.url.searchParams.get('tab')==='files'?'Files & versions':'Overview';
  $: product=$creatorProducts.find((item)=>item.slug===page.params.slug);
  let seededSlug='';
  let title='';let category='';let summary='';let description='';let price=0;let extendedPrice=0;
  let compatibility='GameGuru MAX';let maxVersion='Any MAX build';let sourceFiles=false;let dependencies='None';let performance:'Lightweight'|'Mid-range'|'High detail'='Mid-range';let licence='Standard commercial licence';
  let tagsText='';let featuresText='';let contentsText='';let formatsText='';let showcaseVideoUrl='';
  let showcaseVideo:ReturnType<typeof parseShowcaseVideoUrl>=null;let showcaseVideoError='';
  type PreviewUpload={storage:'supabase';bucket:string;path:string;token:string;role:string;name:string;type:string;size:number};
  let versionNumber='';let releaseNotes='';let packageFile:File|undefined;let documentationFile:File|undefined;let packageInput:HTMLInputElement|undefined;let documentationInput:HTMLInputElement|undefined;let packageDragging=false;let versionBusy=false;let versionProgress=0;let versionUploadState:'idle'|'uploading'|'verified'|'failed'='idle';let versionUploadMessage='';
  let previewFiles:File[]=[];let previewBusy=false;let previewProgress=0;let previewMessage='';
  type StoredPackage={id:string;version:string;status:string;isCurrent:boolean;verified:boolean;size:string;created:string;releaseNotes:string;packageName:string;documentationName?:string};
  let storedPackages:StoredPackage[]=[];let storedPackagesLoading=false;let storedPackagesError='';

  $: if(product&&product.slug!==seededSlug){
    seededSlug=product.slug;title=product.title;category=product.category;summary=product.summary;description=product.description;price=product.price;extendedPrice=product.extendedPrice??Number((product.price*2.5).toFixed(2));compatibility=product.compatibility;maxVersion=product.maxVersion;sourceFiles=product.sourceFiles;dependencies=product.dependencies;performance=product.performance;licence=product.licence;tagsText=product.tags.join(', ');featuresText=product.features.join('\n');contentsText=product.contents.join('\n');formatsText=product.formats.join(', ');showcaseVideoUrl=product.showcaseVideoUrl??'';const savedDraft=readVersionDraft(product.slug);versionNumber=savedDraft.versionNumber;releaseNotes=savedDraft.releaseNotes;packageFile=undefined;documentationFile=undefined;void loadStoredPackages(product.slug);
  }
  $: showcaseVideo=parseShowcaseVideoUrl(showcaseVideoUrl);
  $: showcaseVideoError=showcaseVideoUrl.trim()&&!showcaseVideo?'Enter a valid YouTube or Vimeo video URL.':'';
  $: healthItems=product?[Boolean(title.trim()),Boolean(summary.trim()),Boolean(description.trim()),Boolean(category),Boolean(product.images.length),Boolean(product.versions.length),Boolean(licence.trim()),Boolean(compatibility.trim()),!showcaseVideoError]:[];
  $: healthScore=healthItems.length?Math.round(healthItems.filter(Boolean).length/healthItems.length*100):0;
  $: commissionRate=Math.max(0,Math.min(100,Number($creatorProfile.commission||0)));
  $: estimatedCommission=price*(commissionRate/100);
  $: estimatedEarnings=price-estimatedCommission;

  const lines=(value:string)=>value.split(/\r?\n/).map(item=>item.trim()).filter(Boolean);
  const commaList=(value:string)=>value.split(',').map(item=>item.trim()).filter(Boolean);
  const selectedFile=(event:Event)=>(event.currentTarget as HTMLInputElement).files?.[0];
  const formatFileSize=(size:number)=>size>=1024**3?`${(size/1024**3).toFixed(2)} GB`:`${Math.max(1,Math.round(size/1024/1024))} MB`;
  const versionDraftKey=(slug:string)=>`assetguru:version-draft:${slug}`;
  function readVersionDraft(slug:string){
    if(!browser)return {versionNumber:'',releaseNotes:''};
    try{const value=JSON.parse(localStorage.getItem(versionDraftKey(slug))??'{}');return {versionNumber:typeof value.versionNumber==='string'?value.versionNumber:'',releaseNotes:typeof value.releaseNotes==='string'?value.releaseNotes:''};}catch{return {versionNumber:'',releaseNotes:''};}
  }
  function persistVersionDraft(){if(browser&&product)localStorage.setItem(versionDraftKey(product.slug),JSON.stringify({versionNumber,releaseNotes}));}
  function editVersionNumber(event:Event){versionNumber=(event.currentTarget as HTMLInputElement).value;persistVersionDraft();}
  function editReleaseNotes(event:Event){releaseNotes=(event.currentTarget as HTMLTextAreaElement).value;persistVersionDraft();}
  function clearVersionDraft(){if(browser&&product)localStorage.removeItem(versionDraftKey(product.slug));}
  function setPackageFile(file?:File){
    if(file&&!file.name.toLowerCase().endsWith('.zip')){showToast('The asset package must be a ZIP file','warning');return;}
    packageFile=file;versionProgress=0;versionUploadState='idle';versionUploadMessage='';
  }
  function selectPackage(event:Event){setPackageFile(selectedFile(event));}
  function dragPackage(event:DragEvent){event.preventDefault();if(!versionBusy)packageDragging=true;}
  function leavePackage(event:DragEvent){event.preventDefault();packageDragging=false;}
  function dropPackage(event:DragEvent){event.preventDefault();packageDragging=false;if(!versionBusy)setPackageFile(event.dataTransfer?.files?.[0]);}
  function selectDocumentation(event:Event){documentationFile=selectedFile(event);if(versionUploadState==='failed'){versionUploadState='idle';versionUploadMessage='';}}
  function selectPreviews(event:Event){previewFiles=[...((event.currentTarget as HTMLInputElement).files??[])].slice(0,12);previewProgress=0;previewMessage='';}

  async function save(){
    if(!product)return;
    if(!title.trim()){showToast('Enter a product title before saving','warning');tab='Overview';return;}
    if(extendedPrice<price){showToast('Extended licence price cannot be below the standard price','warning');return;}
    if(showcaseVideoError){showToast(showcaseVideoError,'warning');tab='Presentation';return;}
    const patch:any={title,summary,description,price,extendedPrice,compatibility,maxVersion,sourceFiles,dependencies,performance,licence,tags:commaList(tagsText),features:lines(featuresText),contents:lines(contentsText),formats:commaList(formatsText),showcaseVideoUrl:showcaseVideo?.canonicalUrl??''};
    if(category&&category!=='Uncategorised')patch.category=category;
    await updateCreatorProduct(product.slug,patch);
  }
  async function submitReview(){if(product){await save();await setProductStatus(product.slug,'In review');}}
  async function deleteDraft(){if(!product||!confirm(`Delete the draft “${product.title}”? Uploaded files will also be removed.`))return;await removeCreatorProduct(product.slug);await goto('/creator/products');}

  async function loadStoredPackages(slug:string){
    storedPackagesLoading=true;storedPackagesError='';
    try{const response=await apiRequest<{versions:StoredPackage[]}>(`/api/vendor/products/${slug}/versions`,{cache:'no-store'});storedPackages=response.versions??[];}
    catch(error){storedPackages=[];storedPackagesError=error instanceof Error?error.message:'Stored package details could not be loaded.';}
    finally{storedPackagesLoading=false;}
  }

  async function uploadPreviews(){
    if(!product||previewFiles.length<3){showToast('Choose between 3 and 12 preview images','warning');return;}
    previewBusy=true;previewProgress=0;previewMessage='Preparing secure preview uploads…';
    let preparedPaths:string[]=[];
    try{
      const selected=[...previewFiles];
      const response=await apiRequest<{uploads:PreviewUpload[]}>(`/api/vendor/products/${product.slug}/previews`,{method:'POST',body:JSON.stringify({files:selected.map((file)=>({name:file.name,size:file.size,type:file.type}))})});
      preparedPaths=response.uploads.map((upload)=>upload.path);
      const supabase=getSupabaseBrowserClient();
      for(const [index,upload] of response.uploads.entries()){
        const file=selected[index];
        if(!file)throw new Error(`Missing preview file ${index+1}.`);
        previewMessage=`Uploading preview ${index+1} of ${selected.length}…`;
        const {error}=await supabase.storage.from(upload.bucket).uploadToSignedUrl(upload.path,upload.token,file,{contentType:file.type});
        if(error)throw error;
        previewProgress=Math.round(((index+1)/selected.length)*100);
      }
      previewMessage='Verifying previews…';
      await apiRequest(`/api/vendor/products/${product.slug}/previews`,{method:'PATCH',body:JSON.stringify({paths:preparedPaths})});
      await loadCreatorData(true);previewFiles=[];previewProgress=100;previewMessage='Preview gallery uploaded and verified.';showToast('Preview gallery uploaded and verified','success');
    }catch(error){
      if(preparedPaths.length){try{await apiRequest(`/api/vendor/products/${product.slug}/previews`,{method:'DELETE',body:JSON.stringify({paths:preparedPaths})});}catch(cleanupError){console.error('Pending preview cleanup failed',cleanupError);}}
      previewMessage=error instanceof Error?error.message:'Preview upload failed';showToast(`${previewMessage} Existing previews were not changed.`,'warning');
    }finally{previewBusy=false;}
  }

  async function uploadVersion(){
    if(!product||!packageFile||!versionNumber.trim()||releaseNotes.trim().length<10){showToast('Choose a package and enter a version number with release notes','warning');return;}
    versionBusy=true;versionProgress=0;versionUploadState='uploading';versionUploadMessage='Uploading directly to private Cloudflare R2…';
    let preparedVersionId='';
    try{
      const selectedPackage=packageFile;const selectedDocumentation=documentationFile;
      const response=await apiRequest<{versionId:string;uploads:R2BrowserUpload[]}>(`/api/vendor/products/${product.slug}/versions`,{method:'POST',body:JSON.stringify({version:versionNumber,releaseNotes,package:{name:selectedPackage.name,size:selectedPackage.size,type:selectedPackage.type||'application/octet-stream'},documentation:selectedDocumentation?{name:selectedDocumentation.name,size:selectedDocumentation.size,type:selectedDocumentation.type||'application/octet-stream'}:undefined})});
      preparedVersionId=response.versionId;
      const loaded=new Map<string,number>();const totalBytes=response.uploads.reduce((sum,upload)=>sum+upload.size,0);
      const updateProgress=(role:string,bytes:number)=>{loaded.set(role,bytes);versionProgress=Math.round([...loaded.values()].reduce((sum,value)=>sum+value,0)/Math.max(1,totalBytes)*100);};
      for(const upload of response.uploads){const file=upload.role==='package'?selectedPackage:selectedDocumentation;if(!file)continue;await uploadFileToR2(upload,file,(bytes)=>updateProgress(upload.role,bytes));}
      versionUploadMessage='Upload complete. Verifying the stored object size…';
      await apiRequest(`/api/vendor/products/${product.slug}/versions`,{method:'PATCH',body:JSON.stringify({versionId:response.versionId,packageSize:selectedPackage.size,documentationSize:selectedDocumentation?.size})});
      await loadCreatorData(true);await loadStoredPackages(product.slug);clearVersionDraft();versionNumber='';releaseNotes='';packageFile=undefined;documentationFile=undefined;if(packageInput)packageInput.value='';if(documentationInput)documentationInput.value='';versionProgress=100;versionUploadState='verified';versionUploadMessage='Package uploaded to R2 and verified.';showToast('Package uploaded to R2 and verified','success');
    }catch(error){
      if(preparedVersionId){
        try{await apiRequest(`/api/vendor/products/${product.slug}/versions`,{method:'DELETE',body:JSON.stringify({versionId:preparedVersionId})});}catch(cleanupError){console.error('Pending R2 upload cleanup failed',cleanupError);}
      }
      versionUploadState='failed';versionUploadMessage=error instanceof Error?error.message:'Version upload failed';showToast(`${versionUploadMessage} The draft itself was not changed.`,'warning');
    }finally{versionBusy=false;}
  }
</script>

<svelte:head><title>{product?.title ?? 'Product unavailable'} — Creator Hub</title></svelte:head>
{#if product}
<header class="product-head"><a href="/creator/products">← All products</a><div class="head-main"><img src={product.image} alt=""/><div><div class="head-status"><StatusPill status={product.status}/><span>{product.category}</span><span>v{product.version}</span></div><h1>{product.title}</h1><p>Last updated {product.updated} · {product.views.toLocaleString('en-GB')} listing views</p></div><div class="actions">{#if product.status==='Published'}<a class="button button-secondary" href={`/marketplace/${product.slug}`}><Icon name="eye" size={17}/> View listing</a>{/if}<button class="button button-primary" type="button" onclick={save}><Icon name="check" size={17}/> Save changes</button></div></div></header>

{#if product.status==='Changes required'}<div class="notice warning"><Icon name="alert" size={20}/><div><b>Marketplace review requested changes</b><p>{product.moderationNote||'Review the listing and package, then resubmit when the requested changes are complete.'}</p></div><button type="button" onclick={submitReview}>Resubmit for review</button></div>{/if}
{#if product.status==='In review'}<div class="notice review"><Icon name="clock" size={20}/><div><b>This release is being reviewed</b><p>This listing is temporarily unavailable in the marketplace until an administrator approves the release.</p></div><span>Moderation pending</span></div>{/if}

<nav class="tabs glass">{#each ['Overview','Pricing & licence','Files & versions','Presentation','Support'] as item}<button class:active={tab===item} type="button" onclick={()=>tab=item}>{item}</button>{/each}</nav>
<div class="editor-grid">
  <main>
    {#if tab==='Overview'}
      <section class="panel glass"><div class="panel-title"><div><span class="eyebrow">Listing essentials</span><h2>Product information</h2></div><span class="score">Completion <b>{healthScore}%</b></span></div><label>Product title<input bind:value={title} maxlength="120"/></label><div class="two"><label>Category<select bind:value={category}>{#each $catalogueCategories as item}<option value={item.name}>{item.name}</option>{/each}</select></label><label>Performance profile<select bind:value={performance}><option>Lightweight</option><option>Mid-range</option><option>High detail</option></select></label></div><label>Short summary<textarea rows="3" bind:value={summary} maxlength="300"></textarea><small>{summary.length}/300 characters</small></label><label>Full description<textarea rows="10" bind:value={description}></textarea></label><div class="two"><label>Compatibility<input bind:value={compatibility}/></label><label>Minimum MAX version<select bind:value={maxVersion}><option>2024+</option><option>2025+</option><option>2026+</option><option>Any MAX build</option></select></label></div><div class="two"><label>Dependencies<input bind:value={dependencies}/></label><label class="check"><input type="checkbox" bind:checked={sourceFiles}/> Source files included</label></div><label>Search tags<input bind:value={tagsText} placeholder="environment, medieval, modular"/><small>Comma-separated</small></label><label>Key features<textarea rows="5" bind:value={featuresText} placeholder="One feature per line"></textarea></label><label>Package contents<textarea rows="5" bind:value={contentsText} placeholder="One item per line"></textarea></label><label>File formats<input bind:value={formatsText} placeholder="FBX, PNG, WAV"/><small>Comma-separated</small></label></section>
    {:else if tab==='Pricing & licence'}
      <section class="panel glass"><div class="panel-title"><div><span class="eyebrow">Commercial setup</span><h2>Price and licence tiers</h2></div></div><div class="price-grid"><label><span>Standard commercial licence</span><div class="money"><b>£</b><input type="number" min="0" step="0.01" bind:value={price}/></div></label><label><span>Extended team licence</span><div class="money"><b>£</b><input type="number" min="0" step="0.01" bind:value={extendedPrice}/></div></label></div><div class="fee-preview"><span><small>Buyer pays</small><b>£{price.toFixed(2)}</b></span><span><small>Estimated commission ({commissionRate.toFixed(2).replace(/\.00$/,'')}%)</small><b>−£{estimatedCommission.toFixed(2)}</b></span><span><small>Estimated earnings</small><strong>£{estimatedEarnings.toFixed(2)}</strong></span></div><label>Licence summary<textarea rows="7" bind:value={licence}></textarea></label><p class="help-copy">Final commission is calculated server-side from your vendor agreement, category override and the marketplace setting active at checkout.</p></section>
    {:else if tab==='Files & versions'}
      <section class="panel glass files-panel">
        <div class="panel-title files-title">
          <div><span class="eyebrow">Controlled delivery</span><h2>Files and versions</h2><p>Uploaded ZIP packages are stored privately and shown here permanently after verification.</p></div>
          <span class="storage-badge"><Icon name="shield" size={18}/> Private R2 storage</span>
        </div>

        {#if storedPackagesLoading}
          <div class="empty-package-state"><Icon name="refresh" size={36}/><div><h3>Loading stored packages</h3><p>Checking the verified files attached to this product.</p></div></div>
        {:else if storedPackages.length}
          <section class="uploaded-packages" aria-label="Previously uploaded packages">
            <div class="section-heading"><div><span>PREVIOUSLY UPLOADED</span><h3>Your stored packages</h3></div><p>The newest verified upload appears first.</p></div>
            <div class="uploaded-package-list">
              {#each storedPackages as item,index}
                <article class:latest={index===0} class:unverified={!item.verified} class="uploaded-package-card">
                  <div class="uploaded-folder"><FileGlyph kind="folder" size={52}/></div>
                  <div class="uploaded-package-main">
                    <div class="uploaded-status-row"><span>{index===0?'Latest uploaded package':'Earlier package'}</span><strong class:warning={!item.verified}><Icon name={item.verified?'check':'alert'} size={16}/>{item.verified?'Stored privately and verified':'Upload incomplete'}</strong></div>
                    <h3>{item.packageName}</h3>
                    <div class="package-facts">
                      <span><small>Version</small><b>{item.version}</b></span>
                      <span><small>File size</small><b>{item.size}</b></span>
                      <span><small>Uploaded</small><b>{item.created}</b></span>
                      <span><small>Moderation</small><b>{item.status==='pending'?'Pending review':item.status.replaceAll('_',' ')}</b></span>
                    </div>
                    <div class="stored-notes"><small>Release notes</small><p>{item.releaseNotes||'No release notes supplied.'}</p></div>
                    {#if item.documentationName}<div class="stored-document"><FileGlyph kind="file" size={21}/><span><small>Documentation</small><b>{item.documentationName}</b></span></div>{/if}
                  </div>
                </article>
              {/each}
            </div>
          </section>
        {:else}
          <div class="empty-package-state"><FileGlyph kind="folder" size={52}/><div><h3>No ZIP package has been uploaded</h3><p>{storedPackagesError||'Select the asset ZIP in the large upload area below.'}</p></div></div>
        {/if}

        {#if product.status!=='In review'}
          <section class="version-form" aria-label="Upload another package version">
            <div class="version-form-head"><span>NEW VERSION</span><div><h3>{storedPackages.length?'Upload another version':'Upload the first package'}</h3><p>Your version number and release notes are retained on this device until the upload succeeds.</p></div></div>

            <div class="two version-details">
              <label>Version number <em>Required</em><input value={versionNumber} oninput={editVersionNumber} placeholder="For example: 1.1.0"/></label>
              <label>Release notes <em>Required · at least 10 characters</em><textarea rows="5" value={releaseNotes} oninput={editReleaseNotes} placeholder="Describe compatibility changes, fixes and new content."></textarea></label>
            </div>

            <input class="visually-hidden" bind:this={packageInput} type="file" accept=".zip,application/zip,application/x-zip-compressed" onchange={selectPackage}/>
            <button
              class:dragging={packageDragging}
              class:selected={Boolean(packageFile)}
              class="package-dropzone"
              type="button"
              aria-disabled={versionBusy}
              onclick={()=>{if(!versionBusy)packageInput?.click();}}
              ondragover={dragPackage}
              ondragleave={leavePackage}
              ondrop={dropPackage}
            >
              <span class="dropzone-folder"><FileGlyph kind="folder" size={62}/></span>
              {#if packageFile}
                <span class="dropzone-copy"><small>ZIP PACKAGE SELECTED</small><b>{packageFile.name}</b><em>{formatFileSize(packageFile.size)} · Ready to upload</em></span>
                <span class="change-file">Choose a different ZIP</span>
              {:else}
                <span class="dropzone-copy"><small>REQUIRED ASSET PACKAGE</small><b>Drag your ZIP here</b><em>or click anywhere in this box to choose the file</em></span>
                <span class="choose-file">Choose ZIP package</span>
              {/if}
            </button>
            <p class="selection-note">Selecting a file does not upload it. The package is only marked as stored after the verification step completes.</p>

            <div class:complete={Boolean(documentationFile)} class="documentation-picker">
              <span class="documentation-icon"><FileGlyph kind="file" size={26}/></span>
              <span><b>{documentationFile?documentationFile.name:'Optional documentation'}</b><small>{documentationFile?`${formatFileSize(documentationFile.size)} selected`:'PDF, TXT, MD, DOC or DOCX'}</small></span>
              <input class="visually-hidden" bind:this={documentationInput} type="file" accept=".pdf,.txt,.md,.doc,.docx,application/pdf,text/plain" onchange={selectDocumentation}/>
              <button type="button" onclick={()=>documentationInput?.click()}>{documentationFile?'Change file':'Choose documentation'}</button>
            </div>

            <div class="upload-checks"><span class:done={Boolean(versionNumber.trim())}><Icon name={versionNumber.trim()?'check':'plus'} size={16}/> Version number</span><span class:done={releaseNotes.trim().length>=10}><Icon name={releaseNotes.trim().length>=10?'check':'plus'} size={16}/> Release notes</span><span class:done={Boolean(packageFile)}><Icon name={packageFile?'check':'plus'} size={16}/> ZIP selected</span></div>
            {#if packageFile||versionUploadState!=='idle'}<div class:failed={versionUploadState==='failed'} class:verified={versionUploadState==='verified'} class="upload-state"><div><b>{versionUploadState==='verified'?'Upload verified':versionUploadState==='failed'?'Upload failed':versionBusy?'Uploading securely':'Ready to upload'}</b><small>{versionUploadMessage||(packageFile?`${packageFile.name} · ${formatFileSize(packageFile.size)}`:'')}</small></div>{#if versionBusy}<span>{versionProgress}%</span>{/if}<div class="upload-meter"><i style={`width:${versionProgress}%`}></i></div></div>{/if}
            <div class="upload-action"><button class="button button-primary" type="button" disabled={versionBusy||!packageFile||!versionNumber.trim()||releaseNotes.trim().length<10} onclick={uploadVersion}><Icon name="upload" size={19}/>{versionBusy?`Uploading ${versionProgress}%`:!packageFile?'Select a ZIP package to continue':'Upload and verify package'}</button><p>The existing draft and previously uploaded versions remain safe if this upload fails.</p></div>
          </section>
        {/if}
      </section>
    {:else if tab==='Presentation'}
      <section class="panel glass"><div class="panel-title"><div><span class="eyebrow">Buyer confidence</span><h2>Preview gallery</h2></div><span class="score">{product.images.length}/12 images</span></div>{#if product.images.length}<div class="media-grid">{#each product.images as image,index}<div class:cover={index===0}><img src={image} alt={`${product.title} preview ${index+1}`}/><span>{index===0?'Cover image':`Preview ${index+1}`}</span></div>{/each}</div>{:else}<div class="empty-panel"><Icon name="image" size={28}/><b>No preview media uploaded</b><small>A product cannot be approved until its original signed uploads are complete.</small></div>{/if}<div class="video-field"><label>Showcase video <small>Optional · YouTube or Vimeo</small><input type="url" bind:value={showcaseVideoUrl} placeholder="https://www.youtube.com/watch?v=…"/></label>{#if showcaseVideo}<iframe src={showcaseVideo.embedUrl} title={`${product.title} showcase video`} loading="lazy" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe>{:else if showcaseVideoError}<div class="video-error"><Icon name="alert" size={16}/>{showcaseVideoError}</div>{/if}</div><p class="help-copy">Preview media from the approved submission is public. Asset packages remain private and are delivered only through entitlement-checked signed URLs.</p><div class="preview-form"><h3>Upload or replace preview gallery</h3><label>Preview images <small>3–12 JPG, PNG, WebP or GIF files</small><input type="file" accept="image/jpeg,image/png,image/webp,image/gif" multiple onchange={selectPreviews}/></label>{#if previewFiles.length||previewMessage}<div class="upload-state"><div><b>{previewBusy?'Uploading previews':previewProgress===100?'Verified':'Preview selection'}</b><small>{previewMessage||(previewFiles.length?`${previewFiles.length} images selected`:'')}</small></div>{#if previewBusy}<span>{previewProgress}%</span>{/if}<div class="upload-meter"><i style={`width:${previewProgress}%`}></i></div></div>{/if}<button class="button button-primary" type="button" disabled={previewBusy||previewFiles.length<3} onclick={uploadPreviews}><Icon name="upload" size={17}/>{previewBusy?`Uploading ${previewProgress}%`:'Upload preview gallery'}</button></div></section>
    {:else}
      <section class="panel glass"><div class="panel-title"><div><span class="eyebrow">After-sale experience</span><h2>Support and buyer guidance</h2></div></div><div class="support-summary"><span><small>Store response target</small><b>{$storefront.responseTime||'Not configured'}</b></span><span><small>Support email</small><b>{$storefront.supportEmail||'Not configured'}</b></span></div><label>Store support promise<textarea rows="5" readonly value={$storefront.supportPromise||'No support promise has been published.'}></textarea></label><label>Update commitment<textarea rows="5" readonly value={$storefront.updateCommitment||'No update commitment has been published.'}></textarea></label><a class="button button-secondary" href="/creator/storefront"><Icon name="settings" size={17}/> Edit storefront policies</a></section>
    {/if}
  </main>
  <aside>
    <section class="health glass"><span class="eyebrow">Listing health</span><div class="ring" style={`--score:${healthScore*3.6}deg`}><b>{healthScore}</b><small>/100</small></div><h3>{healthScore===100?'Ready for review':'Complete the listing'}</h3><p>This score reflects required listing, package and preview data already stored for this product.</p><ul><li class:done={Boolean(summary&&description)}><Icon name={summary&&description?'check':'plus'} size={14}/> Description complete</li><li class:done={product.versions.length>0}><Icon name={product.versions.length?'check':'plus'} size={14}/> Package uploaded</li><li class:done={product.images.length>0}><Icon name={product.images.length?'check':'plus'} size={14}/> Preview media uploaded</li><li class:done={Boolean(licence)}><Icon name={licence?'check':'plus'} size={14}/> Licence configured</li></ul></section>
    <section class="stats glass"><h3>Product performance</h3><div><span><small>Revenue</small><b>£{product.revenue.toLocaleString('en-GB',{minimumFractionDigits:2})}</b></span><span><small>Sales</small><b>{product.sales.toLocaleString('en-GB')}</b></span><span><small>Conversion</small><b>{product.conversion?`${product.conversion}%`:'—'}</b></span><span><small>Rating</small><b>{product.rating?`${product.rating} ★`:'—'}</b></span></div><a href="/creator/analytics">Open analytics →</a></section>
    <section class="danger glass"><h3>Product actions</h3>{#if product.status==='Published'}<button type="button" onclick={()=>setProductStatus(product.slug,'Retired')}><Icon name="minus" size={16}/> Retire from sale</button>{:else if product.status!=='In review'}<button type="button" onclick={submitReview}><Icon name="check" size={16}/> Submit for review</button>{/if}{#if product.status==='Draft'||product.status==='Changes required'}<button class="destructive" type="button" onclick={deleteDraft}><Icon name="trash" size={16}/> Delete draft and files</button>{/if}</section>
  </aside>
</div>
{:else}
<section class="empty-page glass"><span class="eyebrow">Creator products</span><h1>Product unavailable.</h1><p>This product does not exist or does not belong to your creator account.</p><a class="button button-primary" href="/creator/products">Return to products</a></section>
{/if}

